CREATE TABLE `incidents` (
  `id` int NOT NULL,
  `match_id` int NOT NULL,
  `minute` int DEFAULT NULL,
  `added_minute` int DEFAULT NULL,
  `incident_type` varchar(32) DEFAULT NULL,
  `incident_class` varchar(32) DEFAULT NULL,
  `player_id` int DEFAULT NULL,
  `player_in_id` int DEFAULT NULL,
  `player_out_id` int DEFAULT NULL,
  `home_score` int DEFAULT NULL,
  `away_score` int DEFAULT NULL,
  `is_home` tinyint(1) DEFAULT NULL,
  `reason` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_incidents_match` (`match_id`),
  KEY `fk_incidents_player` (`player_id`),
  KEY `fk_incidents_player_in` (`player_in_id`),
  KEY `fk_incidents_player_out` (`player_out_id`),
  CONSTRAINT `fk_incidents_match` FOREIGN KEY (`match_id`) REFERENCES `matches` (`id`),
  CONSTRAINT `fk_incidents_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_incidents_player_in` FOREIGN KEY (`player_in_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_incidents_player_out` FOREIGN KEY (`player_out_id`) REFERENCES `players` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
