DROP TABLE IF EXISTS `lineups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lineups` (
  `match_id` int NOT NULL,
  `team_id` int NOT NULL,
  `player_id` int NOT NULL,
  `is_starter` tinyint(1) DEFAULT NULL,
  `position` varchar(64) DEFAULT NULL,
  `jersey_number` int DEFAULT NULL,
  `formation` varchar(16) DEFAULT NULL,
  PRIMARY KEY (`match_id`,`team_id`,`player_id`),
  KEY `fk_lineups_team` (`team_id`),
  KEY `fk_lineups_player` (`player_id`),
  CONSTRAINT `fk_lineups_match` FOREIGN KEY (`match_id`) REFERENCES `matches` (`id`),
  CONSTRAINT `fk_lineups_player` FOREIGN KEY (`player_id`) REFERENCES `players` (`id`),
  CONSTRAINT `fk_lineups_team` FOREIGN KEY (`team_id`) REFERENCES `teams` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

